<?php
use App\Models\{Client,User}; use Illuminate\Foundation\Testing\RefreshDatabase; uses(RefreshDatabase::class); beforeEach(function(){file_put_contents(storage_path('app/installed'),now()->toIso8601String());App\Models\WebsiteSetting::query()->create(['site_name'=>'Test','site_url'=>'https://example.test','timezone'=>'UTC']);}); afterEach(fn()=>@unlink(storage_path('app/installed'))); test('client public lifecycle hides private records and exposes due records',function(){Client::factory()->create(['name'=>'Private organization','slug'=>'private']);Client::factory()->published()->create(['name'=>'Public organization','slug'=>'public']);$this->get('/clients')->assertSuccessful()->assertSee('Public organization')->assertDontSee('Private organization');$this->get('/clients/private')->assertNotFound();$this->get('/clients/public')->assertSuccessful();}); test('client admin routes require authentication',function(){$this->get('/content/clients')->assertRedirect('/login');}); test('client validates canonical content',function(){$user=User::factory()->create(['is_active'=>true]);$this->actingAs($user)->post('/content/clients',['name'=>'Organization','slug'=>'../bad','client_type'=>'invented','logo_path'=>'https://example.com/logo.png'])->assertSessionHasErrors(['slug','client_type','logo_path']);}); test('client archive is dependency protected',function(){$client=Client::factory()->published()->create();$section=App\Models\HomepageSection::query()->create(['section_key'=>'clients','display_order'=>1,'is_enabled'=>true,'background_style'=>'default','content_width'=>'standard']);$client->homepageItems()->create(['homepage_section_id'=>$section->id,'item_type'=>'client','title'=>'Fallback','display_order'=>1,'is_active'=>true]);$this->actingAs(User::factory()->create(['is_active'=>true]))->post(route('admin.clients.archive',$client))->assertSessionHasErrors('client');});
